{
  "name": "SpectrAcq3 单通道探测器采集接口",
  "name_en": "SpectrAcq3 Single-Channel Detector Interface",
  "manufacturer": "HORIBA",
  "description": "用于单通道光谱探测器的数据采集设备，可进行连接管理、设置高压偏置、电气触发与采集参数配置，并控制采集启动、暂停、继续和停止，适用于光谱信号采集与触发测量实验。",
  "description_en": "A data acquisition device for single-channel spectroscopy detectors. It supports connection control, high-voltage bias configuration, electrical trigger setup, acquisition parameter definition, and start/pause/continue/stop of acquisitions for spectroscopy signal collection and triggered measurements.",
  "tag_hints": [
    "spectroscopy",
    "single-channel detector",
    "triggered acquisition",
    "HV bias control",
    "time-series data acquisition",
    "HORIBA spectrometer"
  ],
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开与设备的连接。",
      "description_en": "Open the connection to the device."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与设备的连接。",
      "description_en": "Close the connection to the device."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查设备连接是否已打开。",
      "description_en": "Check whether the device connection is open."
    },
    {
      "action_name": "auto-is_busy",
      "description": "检查设备是否忙碌。",
      "description_en": "Check whether the device is busy."
    },
    {
      "action_name": "auto-set_hv_bias_voltage",
      "description": "设置高压偏置电压。",
      "description_en": "Set the high-voltage bias."
    },
    {
      "action_name": "auto-set_acq_set",
      "description": "定义采集参数。",
      "description_en": "Define acquisition set parameters."
    },
    {
      "action_name": "auto-acq_start",
      "description": "按所选触发方式启动采集。",
      "description_en": "Start acquisition using the selected trigger mode."
    },
    {
      "action_name": "auto-acq_stop",
      "description": "停止当前采集。",
      "description_en": "Stop the current acquisition."
    },
    {
      "action_name": "auto-acq_pause",
      "description": "暂停当前采集。",
      "description_en": "Pause the active acquisition."
    },
    {
      "action_name": "auto-acq_continue",
      "description": "继续已暂停的采集。",
      "description_en": "Continue a paused acquisition."
    },
    {
      "action_name": "auto-is_data_available",
      "description": "检查是否有可用采集数据。",
      "description_en": "Check whether acquired data is available."
    },
    {
      "action_name": "auto-force_trigger",
      "description": "发送软件强制触发。",
      "description_en": "Force a software trigger."
    },
    {
      "action_name": "auto-set_trigger_in_polarity",
      "description": "设置输入触发极性。",
      "description_en": "Set input trigger polarity."
    },
    {
      "action_name": "auto-set_in_trigger_mode",
      "description": "设置硬件触发输入模式。",
      "description_en": "Set the hardware trigger input mode."
    },
    {
      "action_name": "auto-clear_error_log",
      "description": "清除错误日志。",
      "description_en": "Clear the error log."
    }
  ]
}

